@FunctionalInterface
interface TriFunction<A, B, C, R> {
    R apply(A a, B b, C c);
}

TriFunction<Integer, Integer, Integer, Integer> sumTrzech = (a, b, c) -> a + b + c;

@FunctionalInterface
interface CheckedFunction<T, R> {
    R apply(T t) throws Exception; // wlasna sygnatura z throws
}

CheckedFunction<String, Integer> parseRisky = s -> Integer.parseInt(s);

@FunctionalInterface
interface StringProcessor {
    String process(String input);

    default StringProcessor andThen(StringProcessor after) {
        return input -> after.process(this.process(input));
    }
}

StringProcessor trim = String::trim;
StringProcessor upper = String::toUpperCase;
StringProcessor combined = trim.andThen(upper);

